        $count = 0;
        $batch = [];
        $sort = 1;
        foreach ($acupoints as $item) {
            $code = $item['meridian'] ?? '';
            if (!isset($codeToId[$code])) {
                $this->command->warn("经脉代码 {$code} 未找到，跳过穴道 {$item['name']}");
                continue;
            }

            $batch[] = [
                'point_id' => $item['id'],
                'meridian_id' => $codeToId[$code],
                'meridian_code' => $code,
                'side' => $item['side'],
                'seq' => $item['seq'],
                'name' => $item['name'],
                'meridian_cn' => $item['meridianCn'] ?? '',
                'color' => $item['color'],
                'obj' => $item['obj'],
                'scale_x' => $item['scale'][0] ?? 1.0,
                'scale_y' => $item['scale'][1] ?? 1.0,
                'scale_z' => $item['scale'][2] ?? 1.0,
                'x' => $item['x'],
                'y' => $item['y'],
                'z' => $item['z'],
                'sort' => $sort++,
                'status' => 1,
                'created_at' => now(),
                'updated_at' => now(),
            ];
            $count++;

            // 分批写入，避免单次 INSERT 过大
            if (count($batch) >= 100) {
                Acupoint::insert($batch);
                $batch = [];
            }
        }

        if (!empty($batch)) {
            Acupoint::insert($batch);
        }

        $this->command->info("穴道数据填充完成（共 {$count} 条）");
    }
